type UserPreferences = {
  theme?: string
  language?: string
  notifications?: boolean
}

async function getUserPreferences(): Promise<UserPreferences | null> {
  try {
    // 'no-store' opts this fetch out of prerendering so it runs on every request
    // instead of once at build time (the default for routes without request-time APIs).
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    })
    if (!res.ok) {
      return null
    }
    return res.json()
  } catch {
    return null
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences()

  if (!preferences) {
    return (
      <div>
        <h2>User Dashboard</h2>
        <p>Unable to load your preferences right now.</p>
      </div>
    )
  }

  return (
    <div>
      <h2>User Dashboard</h2>
      <dl>
        <dt>Theme</dt>
        <dd>{preferences.theme ?? 'default'}</dd>
        <dt>Language</dt>
        <dd>{preferences.language ?? 'en'}</dd>
        <dt>Notifications</dt>
        <dd>{preferences.notifications ? 'Enabled' : 'Disabled'}</dd>
      </dl>
    </div>
  )
}

